// JT-Zero V3 strict height sensitivity A/B.
// One image stream, one KLT/RANSAC correspondence set, one SYNC attitude, same CAD lever arm.
// Branches differ ONLY in TF-Luna slant used to construct camera height:
//   H20: forced slant = 0.200 m
//   H21: forced slant = 0.210 m
// ACTUAL: real TF-Luna slant, for reference only.
#define JTZERO_V3_LEVER_NO_MAIN
#include "ground_motion_live_v3_lever_ab.cpp"
#undef JTZERO_V3_LEVER_NO_MAIN

int main(int argc,char**argv){
  if(argc<7){std::cerr<<"Использование: "<<argv[0]<<" <camera> <luna> <fc> <csv> <camera_yaml> <camera_offset_mm>\n";return 2;}
  const std::string camdev=argv[1],lunadev=argv[2],fcdev=argv[3],csvpath=argv[4],yaml=argv[5];const double offset_m=std::stod(argv[6])/1000.0;
  const cv::Vec3d t_lc_b(envMm("JTZERO_LEVER_X_MM",49.16)/1000.0,envMm("JTZERO_LEVER_Y_MM",0.22)/1000.0,envMm("JTZERO_LEVER_Z_MM",0.0)/1000.0);
  try{
    CameraCalib calib=loadCameraCalib(yaml);Camera cam;cam.openDev(camdev);LunaReader luna;luna.start(lunadev);LeverFcHistoryReader fc;fc.start(fcdev);std::ofstream csv(csvpath,std::ios::trunc);
    csv<<"state,now_ns,frame_ts_ns,frame,camera_age_ms,att_sync_nearest_ms,att_sync_bracket_ms,luna_age_ms,luna_slant_m,down,lever_dh_m,h_actual_m,h20_m,h21_m,actual_x_m,actual_y_m,actual_path_m,h20_x_m,h20_y_m,h20_path_m,h21_x_m,h21_y_m,h21_path_m,actual_inliers,h20_inliers,h21_inliers,actual_scatter_m,h20_scatter_m,h21_scatter_m,roll,pitch,yaw\n";
    cv::setNumThreads(1);std::signal(SIGINT,onSignal);std::signal(SIGTERM,onSignal);const char*window="JT-ZERO — V3 HEIGHT SENSITIVITY: H20 vs H21";cv::namedWindow(window,cv::WINDOW_NORMAL);cv::resizeWindow(window,1280,720);cv::moveWindow(window,0,0);
    enum class State{READY=0,MOVING=1,DONE=2};State state=State::READY;cv::Mat prev;Attitude prev_att{};double prev_ha=0,prev_h20=0,prev_h21=0;int64_t prev_frame_ts=0;Estimate ea,e20,e21;uint64_t frame_id=0;double ra=0,r20=0,r21=0;
    while(g_running){pollfd p{cam.fd,POLLIN,0};int pr=poll(&p,1,20);if(pr<0){if(errno==EINTR)continue;fail("camera poll");}if(pr<=0)continue;while(g_running){
      v4l2_buffer b{};b.type=V4L2_BUF_TYPE_VIDEO_CAPTURE;b.memory=V4L2_MEMORY_MMAP;if(xioctl(cam.fd,VIDIOC_DQBUF,&b)<0){if(errno==EAGAIN)break;fail("VIDIOC_DQBUF");}
      const int64_t now=monoNs(),frame_ts=frameTvToNs(b.timestamp);const double camera_age_ms=(now-frame_ts)*1e-6;cv::Mat raw(1,(int)b.bytesused,CV_8UC1,cam.bufs[b.index].p);cv::Mat gray=cv::imdecode(raw,cv::IMREAD_GRAYSCALE);if(xioctl(cam.fd,VIDIOC_QBUF,&b)<0)fail("VIDIOC_QBUF");if(gray.empty())continue;++frame_id;
      double luna_m=0;int strength=0;int64_t luna_ns=0;Attitude att{};const bool have_luna=luna.latest(&luna_m,&strength,&luna_ns);double bracket=0,nearest=0;const bool have_att=fc.sampleAt(frame_ts,&att,&bracket,&nearest);const double luna_age_ms=have_luna?(now-luna_ns)*1e-6:1e9;
      double down=0,dh=0,ha=0,h20=0,h21=0;if(have_att){const cv::Matx33d W_R_B=attitudeFluToNwu(att);down=-(W_R_B*cv::Vec3d(0,0,-1))[2];dh=(W_R_B*t_lc_b)[2];if(have_luna)ha=luna_m*down-offset_m+dh;h20=0.200*down-offset_m+dh;h21=0.210*down-offset_m+dh;}
      const bool ok=have_luna&&have_att&&down>0.20&&ha>0.05&&h20>0.05&&h21>0.05&&luna_age_ms<200;
      if(state==State::MOVING&&ok&&!prev.empty()&&prev_att.valid&&prev_ha>0){std::vector<cv::Point2f>p0,p1;cv::goodFeaturesToTrack(prev,p0,700,0.01,7);if(p0.size()>=30){std::vector<uchar>st;std::vector<float>err;cv::calcOpticalFlowPyrLK(prev,gray,p0,p1,st,err,{21,21},3);std::vector<cv::Point2f>a,bp;for(size_t i=0;i<p0.size();++i)if(st[i]){a.push_back(p0[i]);bp.push_back(p1[i]);}if(a.size()>=20){cv::Mat mask;cv::findHomography(a,bp,cv::RANSAC,2.0,mask);if(!mask.empty()){std::vector<cv::Point2f>ai,bi;for(size_t i=0;i<a.size();++i)if(mask.at<uchar>((int)i)){ai.push_back(a[i]);bi.push_back(bp[i]);}const double dt=prev_frame_ts?((frame_ts-prev_frame_ts)*1e-9):0;if(ai.size()>=15&&dt>0&&dt<0.2){cv::Vec2d da,d20,d21;int ua=0,u20=0,u21=0;double sa=0,s20=0,s21=0;if(leverV3Step(ai,bi,calib,prev_att,prev_ha,att,ha,&da,&ua,&sa)&&cv::norm(da)<0.20){ea.x+=da[0];ea.y+=da[1];ea.path+=cv::norm(da);ea.inliers=ua;ea.scatter=sa;}if(leverV3Step(ai,bi,calib,prev_att,prev_h20,att,h20,&d20,&u20,&s20)&&cv::norm(d20)<0.20){e20.x+=d20[0];e20.y+=d20[1];e20.path+=cv::norm(d20);e20.inliers=u20;e20.scatter=s20;}if(leverV3Step(ai,bi,calib,prev_att,prev_h21,att,h21,&d21,&u21,&s21)&&cv::norm(d21)<0.20){e21.x+=d21[0];e21.y+=d21[1];e21.path+=cv::norm(d21);e21.inliers=u21;e21.scatter=s21;}}}}}}
      if(ok){prev=gray.clone();prev_att=att;prev_ha=ha;prev_h20=h20;prev_h21=h21;prev_frame_ts=frame_ts;}else{prev.release();prev_att.valid=false;prev_ha=prev_h20=prev_h21=0;prev_frame_ts=0;}
      cv::Mat bgr,video;cv::cvtColor(gray,bgr,cv::COLOR_GRAY2BGR);cv::resize(bgr,video,{870,653});cv::Mat canvas(720,1280,CV_8UC3,cv::Scalar(12,12,12));video.copyTo(canvas(cv::Rect(0,67,870,653)));ru(canvas,"JT-ZERO — V3 HEIGHT SENSITIVITY H20/H21",{22,35},17,{245,245,245},cv::QT_FONT_BOLD);cv::Mat panel=canvas(cv::Rect(870,0,410,720));ru(panel,ok?"СИСТЕМА ГОТОВА":"ЖДИТЕ ДАННЫЕ ДАТЧИКОВ",{18,42},13,ok?cv::Scalar(90,220,90):cv::Scalar(0,210,255),cv::QT_FONT_BOLD);const char*act=state==State::READY?"СЕЙЧАС: ТОЧКА A — НЕ ДВИГАТЬ":state==State::MOVING?"СЕЙЧАС: ДВИЖЕНИЕ A -> B":"СЕЙЧАС: РЕЗУЛЬТАТ ЗАФИКСИРОВАН";ru(panel,act,{18,82},10,{255,255,255},cv::QT_FONT_BOLD);char z[256];snprintf(z,sizeof(z),"Pitch/Roll: %+.2f / %+.2f°",att.pitch*180/kPi,att.roll*180/kPi);ru(panel,z,{18,125},10,{220,220,220});snprintf(z,sizeof(z),"Luna actual: %.0f мм",luna_m*1000);ru(panel,z,{18,160},10,{220,220,220});snprintf(z,sizeof(z),"H cam actual/20/21: %.1f / %.1f / %.1f",ha*1000,h20*1000,h21*1000);ru(panel,z,{18,195},9,{220,220,220});snprintf(z,sizeof(z),"ACTUAL NET: %.1f мм",std::hypot(ea.x,ea.y)*1000);ru(panel,z,{18,255},12,{245,245,245},cv::QT_FONT_BOLD);snprintf(z,sizeof(z),"H20 NET: %.1f мм",std::hypot(e20.x,e20.y)*1000);ru(panel,z,{18,305},12,{245,245,245},cv::QT_FONT_BOLD);snprintf(z,sizeof(z),"H21 NET: %.1f мм",std::hypot(e21.x,e21.y)*1000);ru(panel,z,{18,355},12,{245,245,245},cv::QT_FONT_BOLD);double n20=std::hypot(e20.x,e20.y),n21=std::hypot(e21.x,e21.y);snprintf(z,sizeof(z),"H21/H20 NET: %.5f",n20>1e-9?n21/n20:0);ru(panel,z,{18,410},11,{230,230,230},cv::QT_FONT_BOLD);if(state==State::DONE){snprintf(z,sizeof(z),"ИТОГ A/20/21: %.1f / %.1f / %.1f",ra*1000,r20*1000,r21*1000);ru(panel,z,{18,600},10,{245,245,245},cv::QT_FONT_BOLD);}ru(panel,state==State::READY?"ПРОБЕЛ — СТАРТ":state==State::MOVING?"В B: ПРОБЕЛ — СТОП":"Q / ESC — ВЫХОД",{18,675},11,{210,210,210},cv::QT_FONT_BOLD);cv::imshow(window,canvas);int rk=cv::waitKeyEx(10),key=rk<0?-1:(rk&0xff);if(cv::getWindowProperty(window,cv::WND_PROP_VISIBLE)<1){g_running=false;break;}if(key==' '&&ok){if(state==State::READY){ea={};e20={};e21={};prev.release();prev_att.valid=false;prev_ha=prev_h20=prev_h21=0;prev_frame_ts=0;state=State::MOVING;}else if(state==State::MOVING){ra=std::hypot(ea.x,ea.y);r20=std::hypot(e20.x,e20.y);r21=std::hypot(e21.x,e21.y);state=State::DONE;std::cout<<"RESULT ACTUAL/H20/H21 NET: "<<ra*1000<<" / "<<r20*1000<<" / "<<r21*1000<<" mm\n";std::cout<<"RESULT H21/H20 ratio: "<<(r20>1e-9?r21/r20:0)<<"\n";}}
      if(key=='q'||key=='Q'||key==27){g_running=false;break;}if(csv){csv<<(int)state<<','<<now<<','<<frame_ts<<','<<frame_id<<','<<std::fixed<<std::setprecision(6)<<camera_age_ms<<','<<nearest<<','<<bracket<<','<<luna_age_ms<<','<<luna_m<<','<<down<<','<<dh<<','<<ha<<','<<h20<<','<<h21<<','<<ea.x<<','<<ea.y<<','<<ea.path<<','<<e20.x<<','<<e20.y<<','<<e20.path<<','<<e21.x<<','<<e21.y<<','<<e21.path<<','<<ea.inliers<<','<<e20.inliers<<','<<e21.inliers<<','<<ea.scatter<<','<<e20.scatter<<','<<e21.scatter<<','<<att.roll<<','<<att.pitch<<','<<att.yaw<<'\n';if((frame_id&3u)==0u)csv.flush();}
    }}cv::destroyAllWindows();std::cout<<"CSV: "<<csvpath<<"\n";return 0;
  }catch(const std::exception&e){std::cerr<<"GROUND MOTION V3 H20/H21 AB FAIL: "<<e.what()<<"\n";return 1;}
}
